// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 v) public {
        vm.assume(amount <= VALUE_CAP);
        // admissible domain: a sane deposit, then withdraw a part (strictly less than the balance)
        vm.assume(amount > 1 && amount < 1e30);
        v = bound(v, 0, amount - 1);

        // fund the owner (deployer) and deposit `amount` into c via its receive()
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);

        uint256 cBefore = address(c).balance;
        vm.assume(v <= cBefore && v < cBefore);

        uint256 ownerBefore = address(this).balance;
        vm.prank(address(this));
        c.withdraw(v);

        // general rule: withdraw(v) pays the caller exactly v; the buggy version
        // always pays the entire balance, which differs from v whenever v < balance.
        assertTrue(address(this).balance - ownerBefore == v);
    }
}
